import { useEffect, useRef, useState } from 'react';
import { FLAVORS, MAX_TRAY_COUNT } from '../../data';
import type { Dispenser, Tray } from '../../types';

interface Props {
  dispenser: Dispenser;
  onCancel: () => void;
  onSubmit: (trays: Tray[]) => Promise<void>;
}

/**
 * Edit the flavor and bean count in each tray. A tray unlocks once the one above it has a flavor,
 * matching how trays are loaded on the physical dispenser.
 */
export default function TraysModal({ dispenser, onCancel, onSubmit }: Props) {
  const dialogRef = useRef<HTMLDialogElement>(null);
  const [trays, setTrays] = useState<Tray[]>(dispenser.trays);
  const [submitting, setSubmitting] = useState(false);
  const [notice, setNotice] = useState('');

  useEffect(() => {
    const dialog = dialogRef.current;
    if (dialog && !dialog.open) dialog.showModal();
  }, []);

  const update = (slot: number, patch: Partial<Tray>) =>
    setTrays((list) => list.map((t) => (t.slot === slot ? { ...t, ...patch } : t)));

  const submit = async () => {
    setSubmitting(true);
    await onSubmit(trays);
    setSubmitting(false);
  };

  return (
    <dialog ref={dialogRef} className="ml-modal ml-modal--wide" aria-labelledby="trays-title" onClose={onCancel}>
      <h2 id="trays-title">Trays Configuration</h2>
      <p className="trays__device">
        <strong>Device name:</strong> <span className="mono">{dispenser.name}</span>
      </p>

      <ol className="trays">
        {trays.map((t, i) => {
          const enabled = i === 0 || !!trays[i - 1].flavorId || !!t.flavorId;
          const hasFlavor = enabled && !!t.flavorId;
          return (
            <li key={t.slot} className={`tray ${enabled ? '' : 'is-disabled'}`}>
              <span className="tray__slot" aria-hidden="true">
                {t.slot}
              </span>
              <label className="ml-field tray__flavor">
                <span>Bean flavor</span>
                <select
                  value={t.flavorId ?? ''}
                  disabled={!enabled}
                  aria-label={`Tray ${t.slot} bean flavor`}
                  onChange={(e) => update(t.slot, { flavorId: e.target.value || null, count: e.target.value ? t.count : 0 })}
                >
                  <option value="">Bean flavor</option>
                  {FLAVORS.map((f) => (
                    <option key={f.id} value={f.id}>
                      {f.name}
                    </option>
                  ))}
                </select>
              </label>
              <label className="ml-field tray__count">
                <span>Count</span>
                <input
                  type="number"
                  inputMode="numeric"
                  min={0}
                  max={MAX_TRAY_COUNT}
                  step={1}
                  value={t.count}
                  disabled={!hasFlavor}
                  aria-label={`Tray ${t.slot} bean count`}
                  onChange={(e) => {
                    const n = Math.floor(Number(e.target.value));
                    update(t.slot, { count: Number.isFinite(n) ? Math.max(0, Math.min(MAX_TRAY_COUNT, n)) : 0 });
                  }}
                />
              </label>
              {/* Placeholder device actions until the dispenser API defines them. */}
              <button
                type="button"
                className="tray__action"
                disabled={!hasFlavor}
                aria-label={`Tray ${t.slot} action A (placeholder)`}
                onClick={() => setNotice(`Tray ${t.slot}: action A is not wired up yet.`)}
              >
                ◐
              </button>
              <button
                type="button"
                className="tray__action"
                disabled={!hasFlavor}
                aria-label={`Tray ${t.slot} action B (placeholder)`}
                onClick={() => setNotice(`Tray ${t.slot}: action B is not wired up yet.`)}
              >
                ●
              </button>
              {hasFlavor && t.count === 0 && (
                <p className="tray__warn">Count is 0, so this flavor won&rsquo;t appear in the demo.</p>
              )}
            </li>
          );
        })}
      </ol>
      <p className="admin__muted trays__notice" role="status">
        {notice}
      </p>

      <div className="ml-modal__actions">
        <button type="button" className="btn btn--ghost" onClick={() => dialogRef.current?.close()}>
          Cancel
        </button>
        <button type="button" className="btn btn--primary btn--purple" disabled={submitting} onClick={submit}>
          {submitting ? 'Saving...' : 'Submit'}
        </button>
      </div>
    </dialog>
  );
}
